import networkx as nx
G = nx.Graph()
for i in range(15):
    G.add_node(i)
for i in range(15):
    for j in range(i+1, 15):
        if len(list(G.neighbors(i))) < 6 and len(list(G.neighbors(j))) < 6 and not G.has_edge(i, j):
            G.add_edge(i, j)
            if len(list(G.neighbors(i))) == 6 or len(list(G.neighbors(j))) == 6:
                break
if min(G.degree(), key=lambda x: x[1])[1] < 3 or max(G.degree(), key=lambda x: x[1])[1] > 6 or nx.girth(G) < 6:
    print("UNSATISFIABLE")
else:
    print(list(G.edges()))
